"""Complete-payload and owning-record evidence checks shared by reviewed exports."""

from __future__ import annotations

import hashlib
import json


def payload_sha256(payload: dict) -> str:
    """Hash the entire reviewed payload, including structured source qualifiers."""
    return hashlib.sha256(
        json.dumps(
            payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False
        ).encode()
    ).hexdigest()


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"Duplicate JSON key: {key}")
        result[key] = value
    return result


def _proof(content: bytes, name: str) -> dict:
    result = json.loads(content, object_pairs_hook=_unique_object)
    if not isinstance(result, dict):
        raise ValueError(f"Expected JSON object: {name}")
    return result


def validate_review_decision(
    decision: dict,
    payload: dict,
    owner: str,
    owner_sha256: str,
    verified: dict[str, bytes],
    proofs: dict,
    *,
    require_owner_path: bool = False,
) -> None:
    """Verify a complete claim against the existing owner/evidence review format.

    Callers independently resolve the owning record and verify every input's
    digest before supplying its bytes. This verifier is shared by mapping and
    companion-claim exports; a checksum or receipt alone confers no approval.
    """
    if (
        decision.get("row_sha256") != payload_sha256(payload)
        or decision.get("owner_record") != owner
    ):
        raise ValueError("Review row payload or owner does not match source")
    if decision.get("disposition") not in {"SUPPORTED", "WITHHOLD"}:
        raise ValueError("Invalid scientific disposition")
    if not isinstance(decision.get("review_reason"), str) or not decision["review_reason"].strip():
        raise ValueError("Missing scientific review reason")
    evidence, key = decision.get("review_evidence"), decision.get("evidence_key")
    if evidence not in verified or not isinstance(key, str) or not key.strip():
        raise ValueError("Missing hash-bound evidence reference")
    if evidence not in proofs:
        proofs[evidence] = _proof(verified[evidence], evidence)
    entry = proofs[evidence].get("entries", {}).get(key)
    expected = {field: decision[field] for field in ("row_sha256", "disposition", "review_reason")}
    expected["owner_record_sha256"] = owner_sha256
    if require_owner_path:
        expected["owner_record"] = owner
    if not isinstance(entry, dict) or any(
        entry.get(field) != value for field, value in expected.items()
    ):
        raise ValueError("Scientific decision disagrees with exact evidence entry")

"""Reviewed MICRO identifiers backed by the pinned KG-Microbe ontology extract.

Some MicrO classes use legacy ``MicrO.owl/MICRO_`` IRIs. KG-Microbe assigns
them MICRO CURIEs. Keep that explicit correspondence instead of treating an
unresolvable canonical IRI as evidence that the ontology class does not exist.
Only individually reviewed entries in the manifest are accepted here.
"""

from __future__ import annotations

import csv
import hashlib
import json
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

SOURCE = Path(__file__).resolve().parent / "ontology_sources" / "micro"


@dataclass(frozen=True)
class MicroTerm:
    """A reviewed source identifier, label, original IRI and parent references."""

    curie: str
    label: str
    iri: str
    parents: tuple[str, ...]


def load_source(directory: Path = SOURCE) -> dict[str, MicroTerm]:
    """Validate the archived evidence before admitting any source-backed term."""
    manifest = json.loads((directory / "manifest.json").read_text())
    tables = {}
    for filename in ("micro_nodes.tsv", "micro_edges.tsv", "legacy_nodes.tsv"):
        path = directory / filename
        expected = manifest["files"][filename]
        if hashlib.sha256(path.read_bytes()).hexdigest() != expected["sha256"]:
            raise ValueError(f"MICRO source checksum mismatch: {filename}")
        with path.open(encoding="utf-8", newline="") as handle:
            tables[filename] = list(csv.DictReader(handle, delimiter="\t"))
        if len(tables[filename]) != expected["records"]:
            raise ValueError(f"MICRO source row count mismatch: {filename}")
    nodes = {row["id"]: row for row in tables["micro_nodes.tsv"]}
    legacy = {row["id"]: row for row in tables["legacy_nodes.tsv"]}
    terms = {}
    for curie, reviewed in manifest["reviewed_terms"].items():
        iri = reviewed["iri"]
        expected_iri = "http://purl.obolibrary.org/obo/MicrO.owl/" + curie.replace(":", "_")
        if iri != expected_iri:
            raise ValueError(f"MICRO source IRI mismatch: {curie}")
        legacy_id = iri.replace("http://purl.obolibrary.org/obo/", "OBO:")
        for node in (nodes.get(curie), legacy.get(legacy_id)):
            if (
                not node
                or node["name"] != reviewed["label"]
                or node.get("deprecated", "").lower() not in {"", "false", "0"}
            ):
                raise ValueError(f"MICRO source label or status mismatch: {curie}")
        parents = tuple(
            sorted(
                row["object"]
                for row in tables["micro_edges.tsv"]
                if row["subject"] == curie and row["predicate"] == "biolink:subclass_of"
            )
        )
        if not parents or list(parents) != sorted(reviewed["parents"]):
            raise ValueError(f"MICRO source parent mismatch: {curie}")
        if any(parent not in nodes for parent in parents):
            raise ValueError(f"MICRO source parent node missing: {curie}")
        terms[curie] = MicroTerm(curie, reviewed["label"], iri, parents)
    return terms


@lru_cache(maxsize=1)
def _reviewed_terms() -> dict[str, MicroTerm]:
    return load_source()


def source_term(curie: str) -> MicroTerm | None:
    """Resolve a reviewed term, without admitting other nodes in the snapshot."""
    return _reviewed_terms().get(curie)

"""Shared policy for labels retained in an ingredient's synonym history."""

from __future__ import annotations

import re
from collections.abc import Mapping
from typing import Any

# These entries preserve a rejected candidate and its provenance in curated
# YAML.  They are not names the record answers to and must not be exposed by
# search/resolution exports or by the SSSOM ``other`` synonym channel.
NON_RESOLVING_SYNONYM_TYPES = frozenset({"REJECTED_LABEL"})

# Curation strings that live in ``synonyms`` but are not names anything answers
# to: role/property annotations carried over from the CultureMech import,
# CultureMech original-amount notes, and bare parentheticals like
# ``(sodium salt)`` or ``(for solid medium, alternative)`` that are fragments of
# a name, not a name. Publishing them as resolvable labels would make internal
# notes resolve to real ingredients.
_CURATION_NOTE_SYNONYM_TEXT = r"^\s*(?:role|properties|cross-references?|original amount)\s*:"
# Organism assay assertions name a relationship to an ingredient, not the
# ingredient itself (#703). Require the complete prefix and colon: chemical
# ratios, CURIEs, and names such as "reduction indicator" remain valid labels.
_TRAIT_SYNONYM_TEXT = (
    r"^\s*(?:produces|reduction|degradation|hydrolysis|electron acceptor|"
    r"aerobic catabolization|anaerobic catabolization|assimilation|growth|"
    r"fermentation|oxidation(?: in darkness)?)\s*:"
)
_BARE_PARENTHETICAL = r"^\s*\([^)]*\)\s*$"

CURATION_NOTE_SYNONYM_TEXT = re.compile(_CURATION_NOTE_SYNONYM_TEXT, re.IGNORECASE)
NON_RESOLVING_SYNONYM_TEXT = re.compile(
    f"{_CURATION_NOTE_SYNONYM_TEXT}|{_TRAIT_SYNONYM_TEXT}|{_BARE_PARENTHETICAL}",
    re.IGNORECASE,
)


def is_curation_note_synonym_text(text: Any) -> bool:
    """Return whether synonym text is an importer or curator note."""
    if not text:
        return False
    return bool(CURATION_NOTE_SYNONYM_TEXT.match(str(text)))


def is_resolving_synonym_text(text: Any) -> bool:
    """Return whether synonym text is a real label for a record."""
    if not text:
        return False
    return not NON_RESOLVING_SYNONYM_TEXT.match(str(text))


def is_resolving_synonym(synonym: Mapping[str, Any]) -> bool:
    """Return whether a synonym row is allowed to resolve to its record."""
    synonym_type = str(synonym.get("synonym_type") or "").strip().upper()
    if synonym_type in NON_RESOLVING_SYNONYM_TYPES:
        return False
    return is_resolving_synonym_text(synonym.get("synonym_text"))


def preferred_term_owners(records: Mapping[str, Mapping[str, Any]]) -> dict[str, frozenset[str]]:
    """Native Rule K ownership, including credited or unresolved tombstones.

    Callers supply the complete mapped-directory snapshot, keyed by forward
    escaped MIM subjects. An explicit representative takes precedence even when
    empty or unresolved; only an absent representative permits legacy fallback.
    """

    def rejected(data: Mapping[str, Any]) -> bool:
        return str(data.get("mapping_status") or "").strip().upper() == "REJECTED"

    live_by_identifier: dict[str, set[str]] = {}
    for subject, data in records.items():
        identifier = str(data.get("identifier") or "").strip()
        if identifier and not rejected(data):
            live_by_identifier.setdefault(identifier, set()).add(subject)
    owners: dict[str, set[str]] = {}
    for subject, data in records.items():
        term = str(data.get("preferred_term") or "").strip()
        if not term:
            continue
        if rejected(data):
            target = (
                data.get("representative") if "representative" in data else data.get("identifier")
            )
            credited = live_by_identifier.get(str(target or "").strip())
            owners.setdefault(term.casefold(), set()).update(credited or {subject})
        else:
            owners.setdefault(term.casefold(), set()).add(subject)
    return {term: frozenset(subjects) for term, subjects in owners.items()}
